#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int radix = 255;
long fraction = 0;
long range = 1;
int cc[2000000];

int OFF1 = 12;
int OFF2 = 6;
int INTOFF = 9;
int LITSIZE = 4;

unsigned char out_buf[1000000];
int out_len = 0;

void pc(int c) {
  out_buf[out_len++] = c;
}

void put_bit(int the_bit, int ctx) {
  while (range < radix) {
    long b = fraction / range;
    pc(b + 1);
    fraction %= range;
    range *= radix;
    fraction *= radix;
  }
  int *counts = cc + ctx * 2;
  int split = range * -~*counts / (*counts + counts[ 1 ] + 2);
  if (the_bit) {
    fraction += split;
    range -= split;
  } else {
    range = split;
  }
  counts[the_bit]++;
}

void put_integer(int val, int tmp, int ctx) {
  int subtract_it = 1 << tmp;
  int original_tmp = tmp;
  int target = val + subtract_it;
  ctx *= 99;

  int m = 0;
  for (int i = 31; i >= 0; i--) {
    if (target & (1 << i)) {
      m = i;
      break;
    }
  }

  int cur_tmp = original_tmp;
  while (cur_tmp < m) {
    put_bit(0, ++cur_tmp + ctx);
  }
  put_bit(1, ++cur_tmp + ctx);

  for (int i = m - 1; i >= 0; i--) {
    int b = (target >> i) & 1;
    put_bit(b, cur_tmp + ctx);
  }
}

void finish() {
  while (range < radix) {
    long b = fraction / range;
    pc(b + 1);
    fraction %= range;
    range *= radix;
    fraction *= radix;
  }
}

int main() {
  FILE *f = fopen("/app/data.txt", "rb");
  if (!f) { perror("fopen"); return 1; }
  fseek(f, 0, SEEK_END);
  long size = ftell(f);
  fseek(f, 0, SEEK_SET);
  char *text = malloc(size + 1);
  fread(text, 1, size, f);
  fclose(f);

  out_len = 0;
  fraction = 0;
  range = 1;
  memset(cc, 0, sizeof(cc));

  put_integer(size, INTOFF, 0);

  long pos = 0;
  while (pos < size) {
    int best_len = 0;
    int best_offset = 0;

    int max_window = 1 << OFF1;
    int max_len = (1 << OFF2);
    int start_w = pos - max_window;
    if (start_w < 0) start_w = 0;

    for (int w = start_w; w < pos; w++) {
      int len = 0;
      while (pos + len < size && len < max_len && text[w + len] == text[pos + len]) {
        len++;
      }
      if (len > best_len) {
        best_len = len;
        best_offset = (pos - 1) - w;
      }
    }

    if (best_len >= 2) {
      put_bit(1, 1);
      put_integer(best_offset, OFF1, 2);
      put_integer(best_len - 1, OFF2, 3);
      pos += best_len;
    } else {
      put_bit(0, 1);
      signed char sc = text[pos];
      int sign = sc < 0 ? 1 : 0;
      int val = sc < 0 ? -sc : sc;
      put_bit(sign, 8);
      put_integer(val, LITSIZE, 9);
      pos++;
    }
  }

  finish();

  FILE *out = fopen("/app/data.comp", "wb");
  fwrite(out_buf, 1, out_len, out);
  fclose(out);

  printf("Compressed size: %d bytes\n", out_len);
  return 0;
}
