int out_len = 0;

void pc(int c) {
  out_buf[out_len++] = c;
}

void put_bit(int the_bit, int ctx) {
  while (range < radix) {
    long b = fraction / range;
    pc(b + 1);
    fraction %= range;
    range *= radix;
    fraction *= radix;
  }
  int *counts = cc + ctx * 2;
  int split = range * -~*counts / (*counts + counts[ 1 ] + 2);
  if (the_bit) {
    fraction += split;
    range -= split;
  } else {
    range = split;
  }
  counts[the_bit]++;
}

void put_integer(int val, int tmp, int ctx) {
  int subtract_it = 1 << tmp;
  int original_tmp = tmp;
  int target = val + subtract_it;
  ctx *= 99;

  int m = 0;
  for (int i = 31; i >= 0; i--) {
    if (target & (1 << i)) {
      m = i;
      break;
    }
  }

  int cur_tmp = original_tmp;
  while (cur_tmp < m) {
    put_bit(0, ++cur_tmp + ctx);
  }
  put_bit(1, ++cur_tmp + ctx);

  for (int i = m - 1; i >= 0; i--) {
    int b = (target >> i) & 1;
    put_bit(b, cur_tmp + ctx);
  }
}

void finish() {
  while (range < radix) {
    long b = fraction / range;
    pc(b + 1);
    fraction %= range;
    range *= radix;
    fraction *= radix;
  }
}

typedef struct {
  int is_match;
  int offset;
  int len;
  unsigned char lit;
} Token;

int main() {
  FILE *f = fopen("/app/data.txt", "rb");
  if (!f) { perror("fopen"); return 1; }
  fseek(f, 0, SEEK_END);
  long size = ftell(f);
  fseek(f, 0, SEEK_SET);
  char *text = malloc(size + 1);
  fread(text, 1, size, f);
  fclose(f);

  Token *tokens = malloc(size * sizeof(Token));
  int token_count = 0;

  long pos = 0;
  int max_window = 1 << OFF1;
  int max_len = 1 << OFF2;

  while (pos < size) {
    int best_len = 0;
    int best_offset = 0;
    int start_w = pos - max_window;
    if (start_w < 0) start_w = 0;

    for (int w = start_w; w < pos; w++) {
      int len = 0;
      while (pos + len < size && len < max_len && text[w + len] == text[pos + len]) {
        len++;
      }
      if (len > best_len) {
        best_len = len;
        best_offset = (pos - 1) - w;
      }
    }

    Token t;
    if (best_len >= 2) {
      t.is_match = 1;
      t.offset = best_offset;
      t.len = best_len;
      pos += best_len;
    } else {
      t.is_match = 0;
      t.lit = text[pos];
      pos++;
    }
    tokens[token_count++] = t;
  }

  out_len = 0;
  fraction = 0;
  range = 1;
  memset(cc, 0, sizeof(cc));

  put_integer(token_count, INTOFF, 0);

  for (int i = 0; i < token_count; i++) {
    if (tokens[i].is_match) {
      put_bit(1, 1);
      put_integer(tokens[i].offset, OFF1, 2);
      put_integer(tokens[i].len - 1, OFF2, 3);
    } else {
      put_bit(0, 1);
      signed char sc = tokens[i].lit;
      int sign = sc < 0 ? 1 : 0;
      int val = sc < 0 ? -sc : sc;
      put_bit(sign, 8);
      put_integer(val, LITSIZE, 9);
    }
  }

  finish();

  FILE *out = fopen("/app/data.comp", "wb");
  fwrite(out_buf, 1, out_len, out);
  fclose(out);

  printf("Compressed size: %d bytes\n", out_len);
  return 0;
}
